27	define(['jquery', 'core/yui', 'core_form/changechecker'], function($, Y, FormChangeChecker) {
28	
29	    /**
30	     * @alias module:mod_quiz/preflightcheck
31	     */
32	    var t = {
33	        confirmDialogue: null,
34	
35	        /**
36	         * Initialise the start attempt button.
37	         *
38	         * @param {String} startButton the id of the start attempt button that we will be enhancing.
39	         * @param {String} confirmationTitle the title of the dialogue.
40	         * @param {String} confirmationForm selector for the confirmation form to show in the dialogue.
41	         * @param {String} popupoptions If not null, the quiz should be launced in a pop-up.
42	         */
43	        init: function(startButton, confirmationTitle, confirmationForm, popupoptions) {
44	            var finalStartButton = startButton;
45	
46	            Y.use('moodle-core-notification', function() {
47	                if (Y.one(confirmationForm)) {
48	                    t.confirmDialogue = new M.core.dialogue({
49	                        headerContent: confirmationTitle,
50	                        bodyContent: Y.one(confirmationForm),
51	                        draggable: true,
52	                        visible: false,
53	                        center: true,
54	                        modal: true,
55	                        width: null,
56	                        extraClasses: ['mod_quiz_preflight_popup']
57	                    });
58	
59	                    Y.one(startButton).on('click', t.displayDialogue);
60	                    Y.one('#id_cancel').on('click', t.hideDialogue);
61	
62	                    finalStartButton = t.confirmDialogue.get('boundingBox').one('[name="submitbutton"]');
63	                }
64	
65	                if (popupoptions) {
66	                    Y.one(finalStartButton).on('click', t.launchQuizPopup, t, popupoptions);
67	                }
68	            });
69	        },
70	
71	        /**
72	         * Display the dialogue.
73	         * @param {Y.EventFacade} e the event being responded to, if any.
74	         */
75	        displayDialogue: function(e) {
76	            if (e) {
77	                e.halt();
78	            }
79	            t.confirmDialogue.show();
80	        },
81	
82	        /**
83	         * Hide the dialogue.
84	         * @param {Y.EventFacade} e the event being responded to, if any.
85	         */
86	        hideDialogue: function(e) {
87	            if (e) {
88	                e.halt();
89	            }
90	            t.confirmDialogue.hide(e);
91	        },
92	
93	        /**
94	         * Event handler for the quiz start attempt button.
95	         * @param {Event} e the event being responded to
96	         * @param {Object} popupoptions
97	         */
98	        launchQuizPopup: function(e, popupoptions) {
99	            e.halt();
100	            Y.use('io-form', function() {
101	                var form = e.target.ancestor('form');
102	
103	                FormChangeChecker.resetFormDirtyState(form.getDOMNode());
104	                window.openpopup(e, {
105	                    url: form.get('action') + '?' + Y.IO.stringify(form).replace(/\bcancel=/, 'x='),
106	                    windowname: 'quizpopup',
107	                    options: popupoptions,
108	                    fullscreen: true,
109	                });
110	            });
111	        }
112	    };
113	
114	    return t;
115	});
